}

.site-title {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.nav-list {
  list-style: none;
  display: flex;
  gap: 22px;
  margin: 0;
  padding: 0;
}

.nav-list a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.95rem;
  padding: 6px 4px;
  border-radius: 4px;
}
.nav-list a:hover { color: var(--text); }
