  color: var(--text);
  border-bottom: 2px solid var(--accent);
}

.preview {
  max-width: 920px;
  margin: 40px auto;
  padding: 0 24px;
}
.preview:focus { outline: none; }

.image-card {
  margin: 0;
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}

.image-card img {
  display: block;
  width: 100%;
  height: auto;
  background: var(--bg-2);
}

.image-card figcaption {
  padding: 18px 22px 20px;
  border-top: 1px solid var(--border);
}

.image-title {
  margin: 0 0 6px;
  font-size: 1.15rem;
  font-weight: 600;
}

.image-meta {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 18px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 500;
  padding: 10px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s, color 0.15s, transform 0.05s;
  background: var(--bg-2);
  color: var(--text);
  border-color: var(--border);
}
.btn:hover { background: var(--bg-3); border-color: var(--border-strong); }
.btn:active { transform: translateY(1px); }

.btn-ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
}
.btn-ghost:hover { background: var(--bg-2); }

.btn-secondary {
  background: var(--bg-3);
  border-color: var(--border-strong);
}

.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn-danger:hover { background: var(--danger-hover); border-color: var(--danger-hover); }

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2, 4, 10, 0.72);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
  animation: fade-in 0.18s ease-out;
}
.dialog-backdrop[hidden] { display: none; }

.dialog {
  position: relative;
  background: var(--bg-1);
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  width: 100%;
  max-width: 460px;
  box-shadow: var(--shadow);
  animation: pop-in 0.22s cubic-bezier(0.2, 0.9, 0.3, 1.1);
}

.dialog-header {
  padding: 22px 24px 4px;
}

.dialog-title {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 600;
}

.dialog-body {
  padding: 8px 24px 16px;
  color: var(--text-muted);
}
.dialog-body strong { color: var(--text); }

.dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 20px 20px;
  border-top: 1px solid var(--border);
  background: var(--bg-1);
  border-radius: 0 0 var(--radius) var(--radius);
}

.dialog-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
}
.dialog-close:hover {
  color: var(--text);
  background: var(--bg-2);
  border-color: var(--border);
}

@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog { animation: none; }
  .btn { transition: none; }
}

@media (max-width: 520px) {
  .site-header { padding: 14px 18px; }
  .actions { justify-content: stretch; }
  .actions .btn { flex: 1; justify-content: center; }
  .dialog-footer { flex-direction: column-reverse; }
  .dialog-footer .btn { width: 100%; justify-content: center; }
}
